              title: "血型与输血",
              level: "高频",
              tags: ["ABO", "Rh", "交叉配血", "新生儿溶血症"],
              body: `一、ABO 血型
红细胞膜抗原（凝集原）决定型：A 型（A 抗原、血清抗 B）、B 型（B 抗原、抗 A）、AB 型（A+B、无抗体）、O 型（无抗原、抗 A+抗 B）。原则同型输血；O 型为万能供血者、AB 型万能受血者（仅应急限少量慢输）。
二、Rh 血型
红细胞含 D 抗原为 Rh 阳性（汉族约 99%），无则阴性。Rh 抗体为免疫性 IgG（天然无），故 Rh 阴性母体首次妊娠 Rh 阳性胎儿一般不发病，再次妊娠可发新生儿溶血症。
三、交叉配血
主侧（献血者 RBC + 受血者血清）+ 次侧（受血者 RBC + 献血者血清）均不凝集方可输血；次侧不合须谨慎。`,
              cards: [
                { q: "ABO 血型的抗原抗体规律？", a: "A 型有 A 抗原+抗 B；B 型有 B 抗原+抗 A；AB 型有 A+B 无抗体；O 型无抗原有抗 A+抗 B。同型输血为原则，异型仅限应急少量。" },
                { q: "Rh 阴性第 2 次妊娠为何可致新生儿溶血症？", a: "Rh 阴性母体首次接触 Rh 阳性胎儿红细胞产生 IgG 抗体，再次妊娠时 IgG 经胎盘破坏胎儿红细胞；Rh 抗体为免疫性 IgG 而非天然抗体。" },
                { q: "交叉配血为何要做主侧与次侧？", a: "主侧（献血者 RBC+受血者血清）最关键，不合即禁输；次侧（受血者 RBC+献血者血清）反映受血者 RBC 是否被凝集，次侧不合须谨慎评估。" }
              ]
