              tags: ["髓质高渗", "直小血管", "逆流交换", "肾血流量", "自身调节"],
              body: `一、尿液浓缩与稀释
肾髓质间质高渗梯度（由髓袢+集合管尿素再循环+直小血管维持）使集合管在 ADH 存在时水重吸收、尿液浓缩；无 ADH 则稀释。
二、直小血管
降支与升支形成逆流交换，带走水、保留溶质，维持髓质高渗不被血流洗脱。
三、肾血流量与自身调节
肾血流量丰富（约 1200ml/min，占心输出量 20%～25%）。自身调节：平均动脉压 80～180mmHg 内肾血流与 GFR 相对稳定（肌源性+管-球反馈）。`,
              cards: [
                { q: "尿液浓缩的机制？", a: "髓质间质高渗梯度（髓袢+尿素再循环+直小血管逆流交换维持）+ 集合管在 ADH 下对水通透→水重吸收→浓缩尿。" },
                { q: "直小血管的作用？", a: "降支/升支逆流交换：带走水、保留溶质（NaCl/尿素），维持髓质高渗不被血流洗脱，保障浓缩能力。" },
                { q: "肾血流量自身调节范围？", a: "平均动脉压 80～180mmHg 内肾血流与 GFR 相对稳定（肌源性+管-球反馈）；超出此范围则随血压变化。" }
              ]
