              level: "高频",
              tags: ["突触", "EPSP", "IPSP", "Ca2+", "总和"],
              body: `一、化学突触传递
动作电位达突触前膜 → Ca²⁺ 内流 → 囊泡量子式释放递质 → 与后膜受体结合 → 突触后电位。兴奋性（EPSP，Na⁺ 内流去极化）或抑制性（IPSP，Cl⁻ 内流/K⁺ 外流超极化）。
二、传递特征
单向传递、突触延搁、总和（时间/空间）、易疲劳、易受药物与内环境（如低钙）影响、可塑性。
三、其他传递
电突触（缝隙连接）双向快速；非定向传递（递质弥散）。`,
              cards: [
                { q: "EPSP 与 IPSP 的机制？", a: "EPSP：递质开 Na⁺ 通道→去极化；IPSP：开 Cl⁻（内流）或 K⁺（外流）通道→超极化；二者均为局部电位、可总和。" },
                { q: "突触传递的特征？", a: "单向、延搁、总和（时间/空间）、易疲劳、易受药物与内环境（如低钙抑释放）影响、可塑。" },
                { q: "突触前膜递质释放的关键离子？", a: "Ca²⁺ 内流触发突触囊泡与前膜融合、量子式释放递质；低钙或肉毒毒素阻断释放→传递受阻。" }
              ]
