          points: [
            {
              id: "p_surgery_004",
              title: "创伤愈合",
              level: "中频",
              tags: ["创伤愈合", "一期愈合", "二期愈合", "肉芽组织", "影响因素"],
              body: `一、基本过程
损伤后：① 炎症期（血小板止血栓+中性粒细胞/巨噬细胞清除坏死与细菌）；② 增生期（成纤维细胞+毛细血管形成肉芽组织、上皮细胞爬行）；③ 塑形期（胶原重塑，瘢痕成熟变白变软）。
二、愈合类型
一期愈合（primary intention）：创缘整齐、对合好、无/少感染（手术切口），愈合快、瘢痕小。
二期愈合（secondary intention）：创口大、缘不齐、有感染坏死（创伤/压疮），需先清创肉芽填充，愈合慢、瘢痕大。
三期愈合（延迟缝合）：污染伤口先开放引流，4~6 天后无感染再缝合。
三、影响愈合的因素
全身：年龄、营养（蛋白质/VC/锌）、糖尿病、免疫低下、吸烟、药物（激素/细胞毒）。
局部：感染（最常见局部因素）、血供差、异物、坏死组织、张力过大。`,
              cards: [
                { q: "一期愈合与二期愈合的主要区别？", a: "一期愈合：创缘整齐对合、无感染（如手术切口），炎症轻、肉芽少，愈合快、瘢痕小。二期愈合：创口大、缘不齐、有坏死/感染（如创伤），需大量肉芽组织填充、上皮爬行距离远，愈合慢、瘢痕大。" },
                { q: "局部因素中影响创伤愈合最常见的是什么？为什么感染会阻碍愈合？", a: "局部最常见阻碍因素是感染。感染时致病菌和中性粒细胞释放的蛋白酶破坏新生组织、消耗营养物质，并持续炎症状态，抑制成纤维细胞和上皮生长，使伤口难以进入增生塑形阶段。" },
                { q: "创伤愈合的基本过程分哪几期？", a: "① 炎症期：血小板止血栓 + 中性粒细胞/巨噬细胞清除坏死与细菌；② 增生期：成纤维细胞与毛细血管形成肉芽组织、上皮爬行；③ 塑形期：胶原重塑，瘢痕成熟变白变软。" }
              ]
            },
            {
              id: "p_surgery_005",
              title: "骨折",
              level: "高频",
              tags: ["骨折", "专有体征", "愈合过程", "并发症", "急救"],
              body: `一、定义与分类
骨的连续性或完整性中断。按是否与外界相通：闭合性/开放性；按程度：不完全/完全；按形态：横、斜、螺旋、粉碎；按稳定性：稳定/不稳定。
二、临床表现与体征
专有体征：畸形、异常活动、骨擦音/骨擦感（三者具其一即可诊断）。
其他：疼痛肿胀、功能障碍、局部淤血。
三、并发症
早期：休克、脂肪栓塞综合征（长骨/骨盆骨折，呼吸困难、瘀点、意识障碍）、重要血管/神经损伤、骨筋膜室综合征（Volkmann 挛缩，最危急，需紧急切开减压）、DIC。
晚期：坠积性肺炎、压疮、深静脉血栓、感染（骨髓炎）、骨不连/延迟愈合、创伤性关节炎、缺血性骨坏死（如股骨颈骨折股骨头坏死）。
四、治疗原则
复位（解剖/功能）、固定（外固定如石膏/夹板、内固定如钢板髓内钉）、功能锻炼（早期肌收缩、循序活动）。
急救：抢救生命优先，开放性骨折先止血包扎、疑脊椎/骨盆伤就地固定勿随意搬动。`,
              cards: [
                { q: "骨折的专有体征有哪些？三者具备其一能否诊断？", a: "专有体征：① 畸形；② 异常活动（非关节部位出现异常活动）；③ 骨擦音或骨擦感。具备三者之一即可临床诊断骨折（不必三者全具），X 线进一步确认并分型。" },
                { q: "骨筋膜室综合征为什么是骨折最危急的早期并发症？如何处理？", a: "骨折出血/水肿使密闭骨筋膜室内压力骤升，阻断微循环，肌肉神经缺血坏死，可致 Volkmann 缺血性挛缩甚至截肢。处理：一经怀疑立即制动、松解外固定/敷料，尽快手术切开筋膜减压，拖延可致不可逆坏死。" },
                { q: "骨折的并发症与治疗原则？", a: "早期并发症：休克、脂肪栓塞、骨筋膜室综合征、重要血管神经损伤；晚期：坠积性肺炎、DVT、感染、骨不连、缺血性骨坏死。治疗：复位（解剖/功能）、固定（外/内固定）、早期功能锻炼；急救先抢救生命，开放性骨折先止血包扎、疑脊柱骨盆伤就地固定勿随意搬动。" }
              ]
            }
          ]
