              body: `一、手术时限与术前准备
按时限：急诊、限期、择期。胃肠道准备：术前 8～12h 禁食、4h 禁饮；肠道手术前 1～2 天流质，结肠直肠手术前清洁灌肠并口服肠道制菌药。预防性抗生素用于感染灶/肠道/时间长/开放/癌肿/植入物/移植等手术。
二、切口分类与愈合
切口：Ⅰ类清洁（疝修补、甲状腺）、Ⅱ类可能污染（胃次全切除）、Ⅲ类污染（肠坏死切除）。愈合：甲级（无不良反应）、乙级（炎症未化脓）、丙级（化脓需引流）。
三、缝线拆除时间
头面颈 4～5 天；下腹会阴 6～7 天；胸上腹背臀 7～9 天；四肢 10～12 天；减张缝线 14 天；电刀切口延迟 1～2 天。`,
