                { q: "术后肺膨胀不全与肺栓塞的要点？", a: "肺膨胀不全多见于上腹术后 48h 内，鼓励咳嗽深呼吸多可自愈；肺栓塞表现为突发呼吸困难、胸痛、咯血，以预防为主（早期活动 + 抗凝）。" },
                { q: "术后出血的判断？", a: "胸腔引流持续 >100ml/h、心率增快、血压下降、CVP<5cmH₂O、尿量 <25ml/h；常需再手术止血并清除血肿。" }
