              body: `一、分类与临床表现
开放伤（穿透/非穿透）与闭合伤。实质脏器（肝脾胃肾）损伤：腹腔内/腹膜后出血、休克，腹痛不剧烈、腹膜刺激轻；空腔脏器（胃肠胆道膀胱）破裂：弥漫性腹膜炎、腹膜刺激征明显。
二、诊断思路
有下列之一考虑内脏损伤：早期休克、进行性腹痛、明显腹膜刺激征、气腹、移动性浊音、便血/呕血/尿血、直肠指诊异常。诊断性腹腔穿刺抽到不凝血（腹膜去纤维作用）提示实质脏器破裂；灌洗更敏感。
三、剖腹探查指征
观察期间恶化（休克加重、腹膜炎进展、肠鸣消失、膈下游离气体、穿刺抽出血胆汁胃肠物、抗休克无效）；处理顺序先止血后处理空腔破裂，先重污染后轻污染。`,
