                { q: "诊断性腹腔穿刺抽得「不凝血」说明什么？", a: "腹膜有去纤维作用使血液不凝，抽到不凝血提示腹腔内实质脏器破裂出血；抽不到也不能排除，可重复穿刺或行腹腔灌洗。" },
                { q: "剖腹探查的指征有哪些？", a: "休克加重、腹膜炎进展或范围扩大、肠鸣音消失、膈下游离气体、穿刺见不凝血/胆汁/胃肠物、抗休克无效等，应尽早手术探查。" }
