                { q: "肝破裂与脾破裂表现差异？", a: "肝破裂因胆汁溢出，腹痛与腹膜刺激更明显，并可发生外伤性胆道出血（黑便/呕血）；脾破裂以出血休克为主、腹膜刺激轻。" },
                { q: "胰腺损伤为何凶险？", a: "胰液强腐蚀致腹腔感染、胰瘘，病死率约 20%；淀粉酶可升高，处理强调充分引流（引流管保留约 10 天），必要时禁食全胃肠外营养。" }
